29	// ExitError reports a non-zero CLI runner exit without terminating the parent
30	// process.
31	type ExitError struct {
32		Code int
33	}
34	
35	func (e *ExitError) Error() string {
36		return fmt.Sprintf("%s exited with code %d", productinfo.BinaryName, e.Code)
37	}
38	
39	// ExitCode extracts a process-style exit code from errors returned by mounted
40	// command execution.
41	func ExitCode(err error) (int, bool) {
42		var exitErr *ExitError
43		if errors.As(err, &exitErr) {
44			return exitErr.Code, true
45		}
46		return 0, false
47	}
