471	func changedFlagArgs(cmd *cobra.Command, names ...string) []string {
472		out := make([]string, 0, len(names)*2)
473		for _, name := range names {
474			flag := cmd.Flags().Lookup(name)
475			if flag != nil && flag.Changed {
476				out = append(out, "--"+name, flag.Value.String())
477			}
478		}
479		return out
480	}
