2263		fmt.Printf("%s %s (commit %s, built %s)\n", productinfo.BinaryName, Version, GitCommit, BuildTime)
2264	
2265		// Skip update check for dev builds or if requested
2266		if Version == "dev" || checkOnly {
2267			return 0
2268		}
2269	
2270		// Check for updates
2271		home, err := os.UserHomeDir()
2272		if err != nil {
2273			return 0 // Can't determine home dir, skip update check
2274		}
2275		cacheFile := filepath.Join(home, ".cache", "fizeau", "latest-version.json")
2276	
2277		release, err := GetLatestRelease(githubRepo, cacheFile)
2278		if err != nil {
2279			fmt.Fprintf(os.Stderr, "  (update check failed: %v)\n", err)
2280			return 0
2281		}
2282	
2283		currentVer, err := ParseSemVer(Version)
2284		if err != nil {
2285			return 0 // Invalid version format, skip comparison
2286		}
2287	
2288		latestVer, err := ParseSemVer(release.TagName)
2289		if err != nil {
2290			return 0 // Invalid latest version, skip comparison
2291		}
2292	
2293		if currentVer.Less(latestVer) {
2294			fmt.Printf("  Update available: %s\n", release.TagName)
2295		} else {
2296			fmt.Println("  (latest)")
2297		}
2298	
2299		return 0
2300	}
