2302	// cmdUpdate checks for and performs updates.
2303	func cmdUpdate(args []string) int {
2304		checkOnly := false
2305		force := false
2306		for _, arg := range args {
2307			switch arg {
2308			case "--check-only", "-c":
2309				checkOnly = true
2310			case "--force", "-f":
2311				force = true
2312			}
2313		}
2314	
2315		// Get current binary path
2316		binaryPath, err := FindBinaryPath()
2317		if err != nil {
2318			fmt.Fprintf(os.Stderr, "error: %v\n", err)
2319			return 1
2320		}
2321	
2322		home, err := os.UserHomeDir()
2323		if err != nil {
2324			fmt.Fprintf(os.Stderr, "error: cannot determine home directory: %v\n", err)
2325			return 1
2326		}
2327		cacheFile := filepath.Join(home, ".cache", "fizeau", "latest-version.json")
2328	
2329		// Get latest release
2330		release, err := GetLatestRelease(githubRepo, cacheFile)
2331		if err != nil {
2332			fmt.Fprintf(os.Stderr, "error: %v\n", err)
2333			return 1
2334		}
2335	
2336		currentVer, err := ParseSemVer(Version)
2337		if err != nil {
2338			fmt.Fprintf(os.Stderr, "error: invalid current version format: %s\n", Version)
2339			return 1
2340		}
2341	
2342		latestVer, err := ParseSemVer(release.TagName)
2343		if err != nil {
2344			fmt.Fprintf(os.Stderr, "error: invalid latest version format: %s\n", release.TagName)
2345			return 1
2346		}
2347	
2348		fmt.Printf("Current: %s\n", Version)
2349		fmt.Printf("Latest:  %s\n", release.TagName)
2350	
2351		if !currentVer.Less(latestVer) {
2352			fmt.Println("\nYou are up to date!")
2353			return 0
2354		}
2355	
2356		if checkOnly {
2357			fmt.Println("\nUpdate available. Run 'fiz update' to upgrade.")
2358			return 1 // Exit code 1 indicates outdated
2359		}

