154		root.AddCommand(nativeUpdateCommand())
155		for _, name := range []string{"version", "run"} {
156			subcommandName := name
157			subcmd := &cobra.Command{
158				Use:           subcommandName,
159				SilenceUsage:  true,
160				SilenceErrors: true,
161				RunE: func(cmd *cobra.Command, args []string) error {
162					legacy := legacyArgs(cmd, append([]string{subcommandName}, args...)...)
163					return runMounted(cfg, legacy)
164				},
165			}
166			if subcommandName == "version" {
167				subcmd.DisableFlagParsing = true
168			}
169			root.AddCommand(subcmd)
170		}
171	}
