// Command fiz is a standalone CLI that wraps the fizeau library.
package main

import (
	"fmt"
	"os"
	"runtime/debug"

	"github.com/DocumentDrivenDX/fizeau/agentcli"
)

// Version info set via -ldflags.
var (
	Version   = "dev"
	BuildTime = ""
	GitCommit = ""
)

func main() {
	version, commit, buildTime := effectiveMeta()
	cmd := agentcli.MountCLI(
		agentcli.WithStdin(os.Stdin),
		agentcli.WithStdout(os.Stdout),
		agentcli.WithStderr(os.Stderr),
		agentcli.WithVersion(version, buildTime, commit),
	)
	args := os.Args[1:]
	if agentcli.NeedsLegacyPassthrough(args) {
		args = append([]string{"--"}, args...)
	}
	cmd.SetArgs(args)
	if err := cmd.Execute(); err != nil {
		if code, ok := agentcli.ExitCode(err); ok {
			os.Exit(code)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// effectiveMeta returns version metadata from ldflags, falling back to Go
// build info VCS settings for dev/local builds that were not stamped.
func effectiveMeta() (version, commit, buildTime string) {
	version = Version
	commit = GitCommit
	buildTime = BuildTime

	// Fully stamped release build — use as-is.
	if version != "" && version != "dev" && commit != "" && buildTime != "" {
		return
	}

	info, ok := debug.ReadBuildInfo()
	if !ok {
		return
	}
	if (version == "" || version == "dev") &&
		info.Main.Version != "" && info.Main.Version != "(devel)" {
		version = info.Main.Version
	}
	for _, s := range info.Settings {
		switch s.Key {
		case "vcs.revision":
			if commit == "" {
				if len(s.Value) > 7 {
					commit = s.Value[:7]
				} else {
					commit = s.Value
				}
			}
		case "vcs.time":
			if buildTime == "" {
				buildTime = s.Value
			}
		}
	}
	return
}

package agentcli

import (
	"encoding/json"
	"fmt"
	"io"
	"runtime/debug"

	"github.com/spf13/cobra"
)

type versionJSON struct {
	Version string `json:"version"`
	Commit  string `json:"commit"`
	Dirty   bool   `json:"dirty"`
	Built   string `json:"built"`
}

// isDirtyBuild reports whether the binary was built from a modified working tree.
func isDirtyBuild() bool {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return false
	}
	for _, s := range info.Settings {
		if s.Key == "vcs.modified" {
			return s.Value == "true"
		}
	}
	return false
}

// cmdVersionJSON writes version metadata as JSON to w.
func cmdVersionJSON(w io.Writer) int {
	v := versionJSON{
		Version: Version,
		Commit:  GitCommit,
		Dirty:   isDirtyBuild(),
		Built:   BuildTime,
	}
	data, err := json.Marshal(v)
	if err != nil {
		fmt.Fprintf(w, "{\"error\":%q}\n", err.Error())
		return 1
	}
	fmt.Fprintln(w, string(data))
	return 0
}

func nativeVersionCommand() *cobra.Command {
	cmd := &cobra.Command{
		Use:           "version",
		Short:         "Print version information",
		SilenceUsage:  true,
		SilenceErrors: true,
		Args:          cobra.NoArgs,
		RunE: func(cmd *cobra.Command, args []string) error {
			if j, _ := cmd.Flags().GetBool("json"); j {
				return exitError(cmdVersionJSON(cmd.OutOrStdout()))
			}
			checkOnly, _ := cmd.Flags().GetBool("check-only")
			if checkOnly {
				return exitError(cmdVersion([]string{"--check-only"}))
			}
			return exitError(cmdVersion(nil))
		},
	}
	cmd.Flags().Bool("json", false, "Output version as JSON")
	cmd.Flags().BoolP("check-only", "c", false, "Only check for updates")
	return cmd
}

