func TestVersionJSONOutput(t *testing.T) {
	oldVersion, oldCommit, oldBuildTime := Version, GitCommit, BuildTime
	t.Cleanup(func() { Version, GitCommit, BuildTime = oldVersion, oldCommit, oldBuildTime })

	var stdout, stderr bytes.Buffer
	cmd := MountCLI(
		WithStdout(&stdout),
		WithStderr(&stderr),
		WithVersion("v1.2.3", "2026-01-01T00:00:00Z", "abc1234"),
	)
	cmd.SetArgs([]string{"version", "--json"})
	if err := cmd.Execute(); err != nil {
		t.Fatalf("Execute: %v", err)
	}

	out := strings.TrimSpace(stdout.String())
	if out == "" {
		t.Fatal("version --json produced no output")
	}

	var result map[string]json.RawMessage
	if err := json.Unmarshal([]byte(out), &result); err != nil {
		t.Fatalf("version --json output is not valid JSON: %v\noutput: %s", err, out)
	}

	checkStringField := func(key, want string) {
		t.Helper()
		raw, ok := result[key]
		if !ok {
			t.Errorf("missing JSON field %q", key)
			return
		}
		var got string
		if err := json.Unmarshal(raw, &got); err != nil {
			t.Errorf("field %q is not a string: %v", key, err)
			return
		}
		if got != want {
			t.Errorf("field %q = %q, want %q", key, got, want)
		}
	}
	checkStringField("version", "v1.2.3")
	checkStringField("commit", "abc1234")

	if _, ok := result["dirty"]; !ok {
		t.Error("missing JSON field \"dirty\"")
	}
	if _, ok := result["built"]; !ok {
		t.Error("missing JSON field \"built\"")
	}
}

