// Command fiz is a standalone CLI that wraps the fizeau library.
package main

import (
	"fmt"
	"os"
	"os/exec"
	"runtime/debug"
	"strings"

	"github.com/DocumentDrivenDX/fizeau/agentcli"
)

// Version info set via -ldflags.
var (
	Version   = "dev"
	BuildTime = ""
	GitCommit = ""
)

func main() {
	version, commit, buildTime := effectiveMeta()
	cmd := agentcli.MountCLI(
		agentcli.WithStdin(os.Stdin),
		agentcli.WithStdout(os.Stdout),
		agentcli.WithStderr(os.Stderr),
		agentcli.WithVersion(version, buildTime, commit),
	)
	args := os.Args[1:]
	if agentcli.NeedsLegacyPassthrough(args) {
		args = append([]string{"--"}, args...)
	}
	cmd.SetArgs(args)
	if err := cmd.Execute(); err != nil {
		if code, ok := agentcli.ExitCode(err); ok {
			os.Exit(code)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// effectiveMeta returns version metadata from ldflags, falling back to Go
// build info VCS settings and then to git for dev/local builds.
func effectiveMeta() (version, commit, buildTime string) {
	version = Version
	commit = GitCommit
	buildTime = BuildTime

	// Fully stamped release build — use as-is.
	if version != "" && version != "dev" && commit != "" && buildTime != "" {
		return
	}

	// Try Go build info (works when VCS info is embedded by go build).
	if info, ok := debug.ReadBuildInfo(); ok {
		if (version == "" || version == "dev") &&
			info.Main.Version != "" && info.Main.Version != "(devel)" {
			version = info.Main.Version
		}
		for _, s := range info.Settings {
			switch s.Key {
			case "vcs.revision":
				if commit == "" {
					if len(s.Value) > 7 {
						commit = s.Value[:7]
					} else {
						commit = s.Value
					}
				}
			case "vcs.time":
				if buildTime == "" {
					buildTime = s.Value
				}
			}
		}
	}

	// Fall back to running git when build info lacks VCS data (e.g. cross-fs worktrees).
	if commit == "" {
		commit = gitShortRef("HEAD")
	}
	return
}

// gitShortRef returns the short hash for ref, or empty string if git is unavailable.
func gitShortRef(ref string) string {
	out, err := exec.Command("git", "rev-parse", "--short", ref).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

